                    }
                    case RegisterOp.I32Load16U:
                    {
                        var address = (ulong)Unsafe.Add(ref v0, frameBase + instr.B).valueI32 + (uint)instr.C;
                        if (address + 2 > memLen) ThrowOutOfBoundsAt(pc);
                        var v = Unsafe.ReadUnaligned<ushort>(ref Unsafe.Add(ref m0, (int)address));
                        ref var d = ref Unsafe.Add(ref v0, frameBase + instr.A);
                        d.valueType = ValueType.I32;
                        d.valueI64 = v;
                        break;
                    }
                    case RegisterOp.I64Load8S:
                    {
                        var address = (ulong)Unsafe.Add(ref v0, frameBase + instr.B).valueI32 + (uint)instr.C;
                        if (address + 1 > memLen) ThrowOutOfBoundsAt(pc);
                        var v = unchecked((ulong)Unsafe.ReadUnaligned<sbyte>(ref Unsafe.Add(ref m0, (int)address)));
