                        c0 = ref compiled.RegisterCode[0];
                        v0 = ref values[0];
                        frameBase = this.frameBase;
                        pc = 0;
                        if (memory != null && memory.Buffer.Length != 0)
                        {
                            m0 = ref memory.Buffer[0];
                            memLen = (ulong)memory.Length;
